#include <iostream>
#include <vector>
#include <queue>
#include <tuple>

using namespace std;

const long long INF = 1e18;

struct Edge {
    int to;
    int time;
    int cost;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int V, N, M;
    if (!(cin >> V >> N >> M)) return 0;

    vector<vector<Edge>> adj(N + 1);
    for (int i = 0; i < M; ++i) {
        int u, v, t, p;
        cin >> u >> v >> t >> p;
        adj[u].push_back({v, t, p});
        adj[v].push_back({u, t, p});
    }

    int X, Y;
    cin >> X >> Y;

    vector<vector<long long>> dist(N + 1, vector<long long>(V + 1, INF));

    // min-heap: (tempo, vertice, custo)
    priority_queue<tuple<long long, int, int>, 
                   vector<tuple<long long, int, int>>, 
                   greater<tuple<long long, int, int>>> pq;

    dist[X][0] = 0;
    pq.emplace(0, X, 0);

    while (!pq.empty()) {
        auto [d, u, c] = pq.top();
        pq.pop();

        if (d > dist[u][c]) continue;
        if (u == Y) {
            // Como é min-heap ordenado pelo tempo, o primeiro a alcançar Y é o de menor tempo
            cout << d << "\n";
            return 0;
        }

        for (const auto& edge : adj[u]) {
            int nc = c + edge.cost;
            if (nc <= V) {
                if (dist[edge.to][nc] > d + edge.time) {
                    dist[edge.to][nc] = d + edge.time;
                    pq.emplace(dist[edge.to][nc], edge.to, nc);
                }
            }
        }
    }

    cout << -1 << "\n";

    return 0;
}
